},
else => |tag| {
_ = (if (bun.Environment.isDebug) blk: {
            break :blk Output.panic("Unexpected AST node: {s}", .{ @tagName(tag) });

} else null);
},
}
    }
};

pub const ConfigIterator = struct {
    allocator: Allocator,
    config: *E.Object,
    source: *const bun.logger.Source,
    log: *bun.logger.Log,
    prop_idx: usize = 0,

pub fn next(self: *ConfigIterator) ?Option(Item) {
            if ((self.prop_idx >= self.config.properties.len)) {
                return null;
            }
            defer {
            self.prop_idx = (self.prop_idx + 1);
            }
            const prop = self.config.properties.ptr[@as(usize, @intCast(self.prop_idx))];
            if (prop.key) |keyexpr| {
